src/normalise.ts:
export type UsageEventInput = {
  account: string;
  occurredAt: string | Date;
  units: number;
  eventId?: string;
};

export type NormalizedUsageEvent = {
  account: string;
  day: string;
  units: number;
  eventId?: string;
};

function getDayString(dateInput: string | Date): string {
  const date = new Date(dateInput);
  if (isNaN(date.getTime())) {
    throw new RangeError('occurredAt cannot be parsed into a valid date');
  }
  // UTC calendar day in YYYY-MM-DD format
  return date.toISOString().slice(0, 10);
}

export function normalizeUsageEvent(input: UsageEventInput): NormalizedUsageEvent {
  // 1. Validate account type
  if (typeof input.account !== 'string') {
    throw new TypeError('account is not a string');
  }

  // 2. Trim and validate account
  const trimmedAccount = input.account.trim();
  if (trimmedAccount.length === 0) {
    throw new RangeError('trimmed account is empty');
  }

  // 3. Validate units type
  if (typeof input.units !== 'number') {
    throw new TypeError('units is not a number');
  }

  // 4. Validate units range
  if (!Number.isFinite(input.units) || input.units < 0 || !Number.isInteger(input.units)) {
    throw new RangeError('units is negative, fractional, NaN, or infinite');
  }

  // 5. Validate occurredAt type
  if (!(typeof input.occurredAt === 'string' || input.occurredAt instanceof Date)) {
    throw new TypeError('occurredAt is neither a string nor a Date');
  }

  // 6. Derive day string
  const day = getDayString(input.occurredAt);

  // 7. Return fresh object
  return {
    account: trimmedAccount,
    day,
    units: input.units,
    eventId: input.eventId,
  };
}

export function normalizeUsageEvents(events: readonly UsageEventInput[]): NormalizedUsageEvent[] {
  // Preserves order and does not mutate input
  return events.map((event) => normalizeUsageEvent(event));
}

src/aggregate.ts:
import type { NormalizedUsageEvent } from './normalise';

export type DailyAccountUsage = {
  day: string;
  account: string;
  eventCount: number;
  units: number;
};

export function aggregateUsage(events: readonly NormalizedUsageEvent[]): DailyAccountUsage[] {
  const groups = new Map<string, { day: string; account: string; eventCount: number; units: number }>();

  for (const event of events) {
    const key = `${event.day}|${event.account}`;
    if (!groups.has(key)) {
      groups.set(key, { day: event.day, account: event.account, eventCount: 0, units: 0 });
    }
    const group = groups.get(key)!;
    group.eventCount += 1;
    group.units += event.units;
  }

  // Convert map values to array
  const result = Array.from(groups.values());

  // Sort deterministically: by day, then by account
  result.sort((a, b) => {
    if (a.day !== b.day) {
      return a.day.localeCompare(b.day);
    }
    return a.account.localeCompare(b.account);
  });

  return result;
}

src/report.ts:
import type { DailyAccountUsage } from './aggregate';

export type AccountUsageTotals = {
  eventCount: number;
  units: number;
  dayCount: number;
};

export type UsageReport = {
  totals: {
    eventCount: number;
    units: number;
    dayCount: number;
    accountCount: number;
  };
  accounts: Record<string, AccountUsageTotals>;
  rows: DailyAccountUsage[];
};

export function buildUsageReport(rows: readonly DailyAccountUsage[]): UsageReport {
  const accounts: Record<string, AccountUsageTotals> = {};
  let totalEventCount = 0;
  let totalUnits = 0;
  const distinctDays = new Set<string>();

  for (const row of rows) {
    totalEventCount += row.eventCount;
    totalUnits += row.units;
    distinctDays.add(row.day);

    if (!accounts[row.account]) {
      accounts[row.account] = { eventCount: 0, units: 0, dayCount: 0 };
    }
    accounts[row.account].eventCount += row.eventCount;
    accounts[row.account].units += row.units;
    accounts[row.account].dayCount += 1;
  }

  // Sort account names for deterministic output
  const sortedAccountKeys = Object.keys(accounts).sort();
  const finalAccounts: Record<string, AccountUsageTotals> = {};
  for (const key of sortedAccountKeys) {
    finalAccounts[key] = accounts[key];
  }

  return {
    totals: {
      eventCount: totalEventCount,
      units: totalUnits,
      dayCount: distinctDays.size,
      accountCount: sortedAccountKeys.length,
    },
    accounts: finalAccounts,
    rows: rows, // Rows are already sorted by aggregateUsage
  };
}

src/main.ts:
export * from './normalise';
export * from './aggregate';
export * from './report';

import { aggregateUsage } from './aggregate';
import { normalizeUsageEvents, type UsageEventInput } from './normalise';
import { buildUsageReport, type UsageReport } from './report';

export function createUsageReport(events: readonly UsageEventInput[]): UsageReport {
  const normalized = normalizeUsageEvents(events);
  const rows = aggregateUsage(normalized);
  return buildUsageReport(rows);
}
